"""Derive SkyyPets/build_skyypets_0.4.24.py from SkyyPets 0.4.23 (SkyyPets/build_skyypets_0.4.23.py = the SET pin, itself GENERATED by
tools/pets_0_4_23_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.23 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_24_patch.py   then   python SkyyPets/build_skyypets_0.4.24.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.24.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.24 (2026-11-08) = RIDING: THE MOUNT NO LONGER BREAKS ON "Interactable" (Skyy 2026-11-08: "riding the horse and dragon is buggy", 2026-11-03: "i cant ride the dragon").
  CAUSE (log 2026-11-08_07-22-46, 8 SEVERE [RoleChangeSystem] Failed to change role: Archetype doesn't contain ComponentType!, the missing one = Interactable):
  the engine's NPCMountSystems$OnAdd ends with a HARD CommandBuffer.removeComponent(Interactable) on every NPC that enters the store with an NPCMountComponent and an
  owner. Vanilla mountable roles keep Interactable alive through ActionSetInteractable; our pet roles have no such action - only PetWorld.prepare at spawn - and nothing
  puts it back: the first mount took it off, MountPlugin.resetOriginalMountRole (get off, our give-up) does not restore it, so every later mount of that creature threw
  inside Store.addEntity (RoleChangeSystem re-adds the NPC with a new Ref). The throw comes after OnAdd has sent MountNPC, so the rest of that add is lost:
  "[Pets] Your Horse could not carry you - press F on it again."
  FIX:
  1. PetRide.mountReal puts Interactable back (PetWorld.interact, only when missing) right before the role change, so OnAdd always has one to take.
  2. PetViews.upkeep puts it back on a summon nobody is on or mounting (no NPCMountComponent), so F and its "Press F" prompt come back after every ride.
  3. mountReal refuses while the creature still is Empty_Role (a give-up / get-off role change still queued): its "original role" would be Empty_Role = a statue for good.
  4. PetRide.second: if your mount id differs from the network id read before the role change, the creature's CURRENT network id is read: you are on it only if that is yours.
  5. INFO lines per server run ("ride <kind>: ..."), 30 for normal rides (mounting, took, got off) + 30 of their own for trouble (retry, gave up, refused, new id, role back),
     so a long session of good rides cannot use up the lines of the one that fails - the client's side cannot be seen on the desk, the next in-game test tells how far a ride got.
  6. F in the ticks while its role is still coming back: "is still settling - press F on it again." (not "could not carry you", not a failed ride).
  7. PetRide.settle (upkeep): a summon nobody is on or mounting that stays Empty_Role for 3 s gets its own role back, so the refusal in 3 can never leave a statue.
  8. PetFight.drop moved after the mount took: a refused mount keeps the pet's fight target (fights untouched).
  NOT CHANGED: fights, pass-through, movement configs, flight, seats, landing. SAVED DATA: none. No new class / system / command / row (one engine-seam method PetWorldApi.interact).
  ROLLBACK: SkyyPets 0.4.24 rolls back alone to 0.4.23 (= riding fails as above); no saved data, no migration. The earlier floors stand.
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.23.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.24.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.23"') and P.has("PASS_FIGHT") and not P.has("REARMED"), "not the generated SkyyPets 0.4.23 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.23 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_23_patch.py from SkyyPets 0.4.22
(build_skyypets_0.4.22.py, the SET pin, itself generated by tools/pets_0_4_22_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.23.py   -> SkyyPets/SkyyPets-0.4.23.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.23.py
''', '''"""SkyyPets 0.4.24 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_24_patch.py from SkyyPets 0.4.23
(build_skyypets_0.4.23.py, the SET pin, itself generated by tools/pets_0_4_23_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.24.py   -> SkyyPets/SkyyPets-0.4.24.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.24.py

''' + NOTE + '''
SkyyPets 0.4.23 (generated by tools/pets_0_4_23_patch.py from 0.4.22) - everything below is still true unless 0.4.24 above says otherwise:
''')
P.rep('VERSION = "0.4.23"\n', 'VERSION = "0.4.24"\n')

# ---- the engine fact the fix rests on: fail the build if OnAdd stops being a hard remove (then this whole round should be looked at again)
P.rep('''# fix round 2: our unmount = the private MountPlugin.resetOriginalMountRole steps; the void line 0 = the engine's own (every world)
''', '''# 0.4.24: NPCMountSystems$OnAdd takes Interactable off with a HARD removeComponent (throws when it is missing), reset does not restore it
_oa = _code("com.hypixel.hytale.builtin.mounts.NPCMountSystems$OnAdd", "onEntityAdded")
assert "CommandBuffer.removeComponent" in _oa and "Interactable.getComponentType" in _oa, "0.4.24: OnAdd no longer removes Interactable the hard way"
assert "Interactable.getComponentType" not in _code("com.hypixel.hytale.builtin.mounts.MountPlugin", "resetOriginalMountRole"), "0.4.24: the engine now restores Interactable itself"
# fix round 2: our unmount = the private MountPlugin.resetOriginalMountRole steps; the void line 0 = the engine's own (every world)
''')

# ---- the seam + PetWorld.interact
P.rep('''            "public abstract Object modelPinned(String id, float scale, String seed);"):       # 0.4.11
''', '''            "public abstract Object modelPinned(String id, float scale, String seed);",       # 0.4.11
            "public abstract boolean interact(@CAC@ acc, @REF@ r);"):       # 0.4.24
''')
P.rep('''# no debug nameplate ("Idle.Default"): only a role with a Debug field sets flags (the vanilla fallback role Test_Pet)
''', '''# 0.4.24: Interactable back on the creature when it is missing (NPCMountSystems$OnAdd removes it at every mount and nothing restores it for
# our roles); true = it was missing and is on again. World thread / ticking system only.
M(pwc, r"""
public static boolean interact(@CAC@ acc, @REF@ r) {
  if (API != null) return API.interact(acc, r);
  if (acc == null || r == null || !r.isValid()) return false;
  try {
    if (acc.getComponent(r, @ITB@.getComponentType()) != null) return false;
    acc.putComponent(r, @ITB@.getComponentType(), @ITB@.INSTANCE);
    return true;
  } catch (Throwable t) { @PKG@.PetsLog.warnOnce("interact:" + t.getClass().getName(), "a pet could not be made usable with F: " + t); return false; }
}""")
# no debug nameplate ("Idle.Default"): only a role with a Debug field sets flags (the vanilla fallback role Test_Pet)
''')

# ---- PetRide: counters + the per-run ride notes
P.rep('''F(rdc, "public static volatile long NOW_OFF = 0L;")          # harness clock
''', '''F(rdc, "public static volatile long NOW_OFF = 0L;")          # harness clock
F(rdc, "public static final java.util.concurrent.atomic.AtomicInteger NOTES = new java.util.concurrent.atomic.AtomicInteger();")          # 0.4.24
F(rdc, "public static final java.util.concurrent.atomic.AtomicInteger NOTES_BAD = new java.util.concurrent.atomic.AtomicInteger();")          # 0.4.24
F(rdc, 'public static final String SETTLING = "it is still settling";')          # 0.4.24
''')
P.rep('''"SWEPT", "REFLY", "UNSTUCK"):''', '''"SWEPT", "REFLY", "UNSTUCK", "REARMED"):''')
P.rep('''", re-set " + REFLY.get() + ", unstuck " + UNSTUCK.get() + ", landings "''', '''", re-set " + REFLY.get() + ", unstuck " + UNSTUCK.get() + ", F restored " + REARMED.get() + ", landings "''')
P.rep('''M(rdc, r"""
public static boolean hasMount(@CAC@ acc, @REF@ r) {
''', '''# 0.4.24: what a ride did (the client's half of a mount cannot be seen on the desk): at most 30 lines per server run for normal rides, 30 of their own for trouble
M(rdc, r"""
public static void note(@PKG@.PetView v, String what) {
  if (v == null || NOTES.incrementAndGet() > 30) return;
  @PKG@.PetsLog.info("ride " + v.kind + " " + v.uuid + ": " + what);
}""")
M(rdc, r"""
public static void noteBad(@PKG@.PetView v, String what) {
  if (v == null || NOTES_BAD.incrementAndGet() > 30) return;
  @PKG@.PetsLog.info("ride " + v.kind + " " + v.uuid + ": " + what);
}""")
M(rdc, r"""
public static boolean hasMount(@CAC@ acc, @REF@ r) {
''')

# ---- the mount: never without Interactable, never from Empty_Role
P.rep('''    if (empty < 0 || orig < 0) return "no ride role loaded";
    @MNT@ c = new @MNT@();
''', '''    if (empty < 0 || orig < 0) return "no ride role loaded";
    if (orig == empty) return SETTLING;          // 0.4.24: its own role is on the way back (give-up / get off): Empty_Role as "original" = a statue for good
    @PKG@.PetWorld.interact(st, pet);          // 0.4.24: OnAdd removes it the hard way when the role change re-adds the creature
    @MNT@ c = new @MNT@();
''')
# ---- a refused mount: the settling wording, the fight target stays; only a mount that goes ahead drops it
P.rep('''  @PKG@.PetFight.drop(v, "ridden");
  String mv = moveId(v.kind);
''', '''  String mv = moveId(v.kind);          // 0.4.24: PetFight.drop is after the mount now
''')
P.rep('''  if (res.length() > 0) {
    v.rideAt = 0L;
    FAILS.incrementAndGet();
    @PKG@.PetsEng.tell(v.owner, "[Pets] Your " + petName(v) + " could not carry you: " + res + ".", "@COLINF@");
    return "-" + res;
  }
''', '''  if (res.length() > 0) {
    v.rideAt = 0L;
    if (SETTLING.equals(res)) {          // 0.4.24: F a tick after getting off: not a failed ride
      @PKG@.PetsEng.tell(v.owner, "[Pets] Your " + petName(v) + " is still settling - press F on it again.", "@COLINF@");
      return "-" + res;
    }
    FAILS.incrementAndGet();
    noteBad(v, "refused: " + res);
    @PKG@.PetsEng.tell(v.owner, "[Pets] Your " + petName(v) + " could not carry you: " + res + ".", "@COLINF@");
    return "-" + res;
  }
  @PKG@.PetFight.drop(v, "ridden");
''')
P.rep('''  v.rideAt = now();
  MOUNTS.incrementAndGet();
''', '''  v.rideAt = now();
  MOUNTS.incrementAndGet();
  note(v, "mounting, network id " + v.netId);
''')

# ---- the per-second watch
P.rep('''  boolean on = mid != 0 && mid == v.netId;
  if (on && !v.riding) {
''', '''  boolean on = mid != 0 && mid == v.netId;
  if (!on && mid != 0 && netId(cb, v.ref) == mid) { noteBad(v, "you are on it under network id " + mid + " (was " + v.netId + ")"); v.netId = mid; on = true; }          // 0.4.24: the id read before the role change may be old; another mount's id never counts
  if (on && !v.riding) {
    note(v, "took, network id " + v.netId);
''')
P.rep('''    DISMOUNTS.incrementAndGet();
''', '''    DISMOUNTS.incrementAndGet();
    note(v, "got off (mount id now " + mid + ", component on it " + hasMount(cb, v.ref) + ")");
''')
P.rep('''      RETRIES.incrementAndGet();
''', '''      RETRIES.incrementAndGet();
      noteBad(v, "not on it after 1 s and no mount component: trying once more (mount id " + mid + ")");
''')
P.rep('''      v.rideAt = 0L;
      if (hasMount(cb, v.ref) && unmount(cb, v.ref)) UNSTUCK.incrementAndGet();          // fix round 2: never leave it an Empty_Role statue
''', '''      v.rideAt = 0L;
      noteBad(v, "gave up: mount id " + mid + ", network id " + v.netId + ", component on it " + hasMount(cb, v.ref) + ", role " + @PKG@.PetWorld.roleOf(cb, v.ref));
      if (hasMount(cb, v.ref) && unmount(cb, v.ref)) UNSTUCK.incrementAndGet();          // fix round 2: never leave it an Empty_Role statue
''')

# ---- settle: never an Empty_Role statue with nobody on it
P.rep('''# every second for a summoned creature (PetViews.upkeep): 0 = go on as usual, 1 = riding / mounting / landing (skip follow + fight),
''', '''# 0.4.24: a summon nobody is on or mounting that stays Empty_Role for 3 upkeep seconds (its role change back was lost): its own role back, so mountReal's
# refusal cannot leave a statue for good; true = asked for. The per-second upkeep only.
M(rdc, r"""
public static boolean settle(@PKG@.PetView v, @CAC@ acc) {
  if (v == null || v.slot != 2 || v.ref == null) return false;
  if (v.riding || v.rideAt > 0L || hasMount(acc, v.ref) || !EMPTY_ROLE.equals(@PKG@.PetWorld.roleOf(acc, v.ref))) { v.emptySecs = 0; return false; }
  v.emptySecs = v.emptySecs + 1;
  if (v.emptySecs < 3) return false;
  v.emptySecs = 0;
  int own = v.role == null ? -1 : @PKG@.PetWorld.roleIndex(v.role);
  if (own < 0 || own == @PKG@.PetWorld.roleIndex(EMPTY_ROLE)) return false;
  noteBad(v, "its own role back after 3 s as Empty_Role with nobody on it");
  if (API != null) return true;
  try {
    @NPC@ npc = (@NPC@) acc.getComponent(v.ref, @NPC@.getComponentType());
    if (npc == null) return false;
    @RCS@.requestRoleChange(v.ref, npc.getRole(), own, false, "Idle", (String) null, acc);
    UNSTUCK.incrementAndGet();
    return true;
  } catch (Throwable t) { @PKG@.PetsLog.warnOnce("settle:" + t.getClass().getName(), "a stuck pet could not get its role back: " + t); return false; }
}""")
# every second for a summoned creature (PetViews.upkeep): 0 = go on as usual, 1 = riding / mounting / landing (skip follow + fight),
''')
P.rep('''"int rideTries",''', '''"int rideTries", "int emptySecs",''')          # 0.4.24

# ---- upkeep: F comes back after a ride (the engine leaves the creature without Interactable)
P.rep('''  pass(cb, v, fighting(cb, o));          // 0.4.23: Intangible only in the owner's fights (never on a summon you can ride)
''', '''  pass(cb, v, fighting(cb, o));          // 0.4.23: Intangible only in the owner's fights (never on a summon you can ride)
  if (v.slot == 2 && !v.riding && v.rideAt <= 0L && !@PKG@.PetRide.hasMount(cb, v.ref) && @PKG@.PetWorld.interact(cb, v.ref)) @PKG@.PetRide.REARMED.incrementAndGet();          // 0.4.24: F comes back after a ride
  @PKG@.PetRide.settle(v, cb);          // 0.4.24: never an Empty_Role statue with nobody on it
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.24 adds no class, system or command"
assert P.s.count("@PKG@.PetWorld.interact(") == 2, "0.4.24: interact at the mount and in upkeep only"
P.finish()
